                days = q / (r['units_sold'] / 30.0) if r['units_sold'] else None
                if days is not None and days < 15:
                    out.append({'title': '库存告急：%s（%s）' % (r['product_name_en'], r['sku']), 'detail': '期末库存 %.0f 箱，9 月销量 %.0f 箱，预计仅可支撑 %.1f 天，需立即补货。' % (q, r['units_sold'], days), 'evidence': {'stock_on_hand': q, 'units_sold': r['units_sold'], 'days_cover': round(days, 1)}})
    trend = pick(['period_start', 'total_amount', 'total_quantity'])
    if trend:
        rows = sorted(trend['rows'], key=lambda r: r['period_start'])
        latest = rows[-1]
        prev = rows[-2] if len(rows) > 1 else None
        if prev:
            chg = (latest['total_amount'] - prev['total_amount']) / prev['total_amount'] * 100
            out.append({'title': '采购金额环比波动', 'detail': '最新报告期采购金额 %.2f，较上期 %.2f 变化 %.1f%%，采购节奏波动较大。' % (latest['total_amount'], prev['total_amount'], chg), 'evidence': {'latest_amount': round(latest['total_amount'], 2), 'prev_amount': round(prev['total_amount'], 2), 'change_percent': round(chg, 1)}})
    sales = pick(['aug_total', 'sep_total', 'change_percent'])
    if sales:
        r = sales['rows'][0]
        out.append({'title': '销售额小幅下滑', 'detail': '9 月已确认销售额 %.2f，较 8 月 %.2f 下降 %.2f%%，销售端承压。' % (r['sep_total'], r['aug_total'], abs(r['change_percent'])), 'evidence': {'sep_total': r['sep_total'], 'aug_total': r['aug_total'], 'change_percent': round(r['change_percent'], 2)}})
    return out
